-- Design contract 0.1.0. PostgreSQL DDL draft; not a running backend.
-- UUIDs are generated by the application. No extension or SaaS tenant is required.
-- Run with a migration owner in an EMPTY application database/schema.
-- Runtime role must not own tables or have TRUNCATE / DDL / trigger-disable rights.
BEGIN;

CREATE TABLE users (
  id uuid PRIMARY KEY,
  username text NOT NULL CHECK (username <> ''),
  display_name text NOT NULL,
  password_hash text NOT NULL,
  role text NOT NULL CHECK (role IN ('admin','agent','reviewer')),
  disabled_at timestamptz,
  last_login_at timestamptz,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  scope_version bigint NOT NULL DEFAULT 1 CHECK (scope_version > 0),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE UNIQUE INDEX users_username_ci_uq ON users (lower(username));

CREATE TABLE user_sessions (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  token_hash bytea NOT NULL UNIQUE CHECK (octet_length(token_hash) = 32),
  csrf_token_hash bytea NOT NULL CHECK (octet_length(csrf_token_hash) = 32),
  created_at timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  idle_expires_at timestamptz NOT NULL,
  expires_at timestamptz NOT NULL,
  revoked_at timestamptz,
  CHECK (expires_at > created_at),
  CHECK (idle_expires_at <= expires_at)
);
CREATE INDEX user_sessions_user_idx ON user_sessions(user_id);
CREATE INDEX user_sessions_expiry_idx ON user_sessions(expires_at) WHERE revoked_at IS NULL;

CREATE TABLE customers (
  id uuid PRIMARY KEY,
  name text NOT NULL CHECK (name <> ''),
  code text UNIQUE,
  disabled_at timestamptz,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE user_customer_scopes (
  user_id uuid NOT NULL REFERENCES users(id),
  customer_id uuid NOT NULL REFERENCES customers(id),
  granted_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (user_id, customer_id)
);
CREATE INDEX user_customer_scopes_customer_idx ON user_customer_scopes(customer_id,user_id);

CREATE TABLE chat_groups (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES customers(id),
  name text NOT NULL,
  external_group_key text,
  timezone text NOT NULL DEFAULT 'Asia/Shanghai' CHECK (timezone = 'Asia/Shanghai'),
  ingestion_version bigint NOT NULL DEFAULT 0 CHECK (ingestion_version >= 0),
  classified_version bigint NOT NULL DEFAULT 0 CHECK (classified_version >= 0),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  archived_at timestamptz,
  created_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,external_group_key),
  CHECK (classified_version <= ingestion_version)
);
CREATE TABLE participants (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  group_id uuid NOT NULL,
  display_name text NOT NULL,
  external_member_key text,
  role text NOT NULL DEFAULT 'unknown' CHECK (role IN ('customer','support','other','unknown')),
  identity_verified boolean NOT NULL DEFAULT false,
  linked_user_id uuid REFERENCES users(id),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,group_id) REFERENCES chat_groups(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,group_id,id),
  UNIQUE (customer_id,group_id,external_member_key)
);
CREATE INDEX participants_group_idx ON participants(customer_id,group_id);

CREATE TABLE import_batches (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  group_id uuid NOT NULL,
  uploaded_by uuid NOT NULL REFERENCES users(id),
  original_filename text NOT NULL,
  storage_key text NOT NULL UNIQUE,
  file_sha256 text NOT NULL CHECK (file_sha256 ~ '^[0-9a-f]{64}$'),
  byte_size bigint NOT NULL CHECK (byte_size >= 0),
  source_encoding text NOT NULL DEFAULT 'UTF-8',
  parser_version text NOT NULL,
  parse_version integer NOT NULL DEFAULT 0 CHECK (parse_version >= 0),
  current_parse_snapshot_id uuid,
  ingestion_version bigint CHECK (ingestion_version > 0),
  confirmed_at timestamptz,
  state text NOT NULL DEFAULT 'uploaded' CHECK (state IN ('uploaded','parsing','needs_review','ready','confirmed','failed')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  message_count integer NOT NULL DEFAULT 0 CHECK (message_count >= 0),
  parse_issues jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(parse_issues) = 'array'),
  created_at timestamptz NOT NULL DEFAULT now(),
  parsed_at timestamptz,
  FOREIGN KEY (customer_id,group_id) REFERENCES chat_groups(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,group_id,id),
  UNIQUE (customer_id,group_id,file_sha256),
  UNIQUE (group_id,ingestion_version),
  CHECK (num_nonnulls(ingestion_version,confirmed_at) IN (0,2))
);
CREATE INDEX import_batches_list_idx ON import_batches(customer_id,created_at DESC,id);

-- Non-AI asynchronous operations share the API Job DTO, but not extraction constraints.
-- A background job has one durable step; its JobStep.id is the same UUID as job.id.
CREATE TABLE background_jobs (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES customers(id),
  kind text NOT NULL CHECK (kind IN ('parse_import','export')),
  batch_id uuid,
  requested_by uuid NOT NULL REFERENCES users(id),
  state text NOT NULL DEFAULT 'queued' CHECK (state IN ('queued','running','succeeded','partial_failed','failed','cancel_requested','cancelled')),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  input_hash text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  input_payload jsonb NOT NULL CHECK (jsonb_typeof(input_payload) = 'object'),
  output_json jsonb,
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  lease_owner text,
  lease_until timestamptz,
  fencing_token bigint NOT NULL DEFAULT 0 CHECK (fencing_token >= 0),
  next_attempt_at timestamptz,
  error_code text,
  error_summary text,
  created_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  finished_at timestamptz,
  cancel_requested_at timestamptz,
  FOREIGN KEY (customer_id,batch_id) REFERENCES import_batches(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,batch_id,id),
  CHECK ((kind = 'parse_import' AND batch_id IS NOT NULL) OR (kind = 'export' AND batch_id IS NULL)),
  CHECK (state <> 'running' OR (lease_owner IS NOT NULL AND lease_until IS NOT NULL)),
  CHECK (finished_at IS NULL OR (finished_at >= created_at AND (started_at IS NULL OR finished_at >= started_at)))
);
CREATE INDEX background_jobs_list_idx ON background_jobs(customer_id,created_at DESC,id);
CREATE INDEX background_jobs_dispatch_idx ON background_jobs(state,next_attempt_at,lease_until);

CREATE TABLE import_parse_snapshots (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  batch_id uuid NOT NULL,
  source_job_id uuid NOT NULL,
  parse_version integer NOT NULL CHECK (parse_version > 0),
  parser_version text NOT NULL,
  parse_config jsonb NOT NULL CHECK (jsonb_typeof(parse_config) = 'object'),
  resolved_encoding text NOT NULL,
  preview_records jsonb NOT NULL CHECK (jsonb_typeof(preview_records) = 'array'),
  warnings jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(warnings) = 'array'),
  record_count integer NOT NULL CHECK (record_count >= 0),
  warning_count integer NOT NULL DEFAULT 0 CHECK (warning_count >= 0),
  error_count integer NOT NULL DEFAULT 0 CHECK (error_count >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,batch_id) REFERENCES import_batches(customer_id,id),
  FOREIGN KEY (customer_id,batch_id,source_job_id) REFERENCES background_jobs(customer_id,batch_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,batch_id,parse_version,id),
  UNIQUE (batch_id,parse_version),
  CHECK (jsonb_array_length(preview_records) = record_count)
);
ALTER TABLE import_batches ADD CONSTRAINT import_batches_parse_snapshot_fk
  FOREIGN KEY (customer_id,id,parse_version,current_parse_snapshot_id)
  REFERENCES import_parse_snapshots(customer_id,batch_id,parse_version,id)
  DEFERRABLE INITIALLY DEFERRED;

CREATE TABLE export_artifacts (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  job_id uuid NOT NULL,
  export_kind text NOT NULL CHECK (export_kind IN ('ticket','qa')),
  format text NOT NULL CHECK (format IN ('csv','json')),
  filename text NOT NULL,
  content_type text NOT NULL,
  storage_key text NOT NULL UNIQUE,
  file_sha256 text NOT NULL CHECK (file_sha256 ~ '^[0-9a-f]{64}$'),
  size_bytes bigint NOT NULL CHECK (size_bytes >= 0),
  snapshot_at timestamptz NOT NULL,
  snapshot_manifest jsonb NOT NULL CHECK (jsonb_typeof(snapshot_manifest) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  deleted_at timestamptz,
  FOREIGN KEY (customer_id,job_id) REFERENCES background_jobs(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (job_id),
  CHECK (expires_at > created_at)
);
CREATE INDEX export_artifacts_expiry_idx ON export_artifacts(expires_at) WHERE deleted_at IS NULL;

CREATE TABLE messages (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  group_id uuid NOT NULL,
  batch_id uuid NOT NULL,
  source_index integer NOT NULL CHECK (source_index >= 0),
  sender_participant_id uuid,
  sender_name_raw text,
  sent_at timestamptz,
  timestamp_raw text,
  raw_header text NOT NULL DEFAULT '',
  raw_text text NOT NULL,
  normalized_text text NOT NULL,
  direct_body_spans jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(direct_body_spans) = 'array'),
  text_sha256 text NOT NULL CHECK (text_sha256 ~ '^[0-9a-f]{64}$'),
  kind text NOT NULL CHECK (kind IN ('text','media_placeholder','system','malformed')),
  source_line_start integer NOT NULL CHECK (source_line_start > 0),
  source_line_end integer NOT NULL CHECK (source_line_end >= source_line_start),
  source_body_start bigint NOT NULL CHECK (source_body_start >= 0),
  source_body_end bigint NOT NULL CHECK (source_body_end >= source_body_start),
  quoted_message_id uuid,
  parse_warnings jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(parse_warnings) = 'array'),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,group_id,batch_id) REFERENCES import_batches(customer_id,group_id,id),
  FOREIGN KEY (customer_id,group_id,sender_participant_id) REFERENCES participants(customer_id,group_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,group_id,id),
  UNIQUE (batch_id,source_index),
  CHECK (source_body_end - source_body_start = char_length(raw_text)),
  CHECK (quoted_message_id IS NULL OR quoted_message_id <> id)
);
ALTER TABLE messages ADD CONSTRAINT messages_quote_fk
  FOREIGN KEY (customer_id,group_id,quoted_message_id) REFERENCES messages(customer_id,group_id,id)
  DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX messages_time_idx ON messages(customer_id,group_id,sent_at,id);
CREATE INDEX messages_candidate_hash_idx ON messages(customer_id,group_id,text_sha256);
CREATE INDEX messages_sender_idx ON messages(customer_id,sender_participant_id);

-- Corrections append interpretation snapshots; the imported raw source never changes.
CREATE TABLE message_annotations (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  group_id uuid NOT NULL,
  message_id uuid NOT NULL,
  annotation_no integer NOT NULL CHECK (annotation_no > 0),
  sender_participant_id uuid,
  sent_at timestamptz,
  quoted_message_id uuid,
  body_text text NOT NULL,
  quoted_text text NOT NULL DEFAULT '',
  direct_body_spans jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(direct_body_spans) = 'array'),
  reason text NOT NULL CHECK (btrim(reason) <> ''),
  created_by uuid NOT NULL REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,group_id,message_id) REFERENCES messages(customer_id,group_id,id),
  FOREIGN KEY (customer_id,group_id,sender_participant_id) REFERENCES participants(customer_id,group_id,id),
  FOREIGN KEY (customer_id,group_id,quoted_message_id) REFERENCES messages(customer_id,group_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (message_id,annotation_no),
  CHECK (quoted_message_id IS NULL OR quoted_message_id <> message_id)
);
CREATE INDEX message_annotations_latest_idx ON message_annotations(customer_id,message_id,annotation_no DESC);

CREATE TABLE message_equivalences (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  group_id uuid NOT NULL,
  message_a_id uuid NOT NULL,
  message_b_id uuid NOT NULL,
  state text NOT NULL CHECK (state IN ('candidate','confirmed','rejected')),
  reason text NOT NULL,
  created_by uuid REFERENCES users(id),
  confirmed_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  confirmed_at timestamptz,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  FOREIGN KEY (customer_id,group_id,message_a_id) REFERENCES messages(customer_id,group_id,id),
  FOREIGN KEY (customer_id,group_id,message_b_id) REFERENCES messages(customer_id,group_id,id),
  UNIQUE (customer_id,group_id,message_a_id,message_b_id),
  CHECK (message_a_id < message_b_id),
  CHECK (state <> 'confirmed' OR (confirmed_by IS NOT NULL AND confirmed_at IS NOT NULL))
);
CREATE INDEX message_equivalences_b_idx ON message_equivalences(customer_id,message_b_id);

CREATE TABLE issues (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  primary_group_id uuid NOT NULL,
  label text NOT NULL,
  lifecycle text NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active','merged')),
  merged_into_id uuid,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  message_version bigint NOT NULL DEFAULT 0 CHECK (message_version >= 0),
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,primary_group_id) REFERENCES chat_groups(customer_id,id),
  UNIQUE (customer_id,id),
  CHECK ((lifecycle = 'active' AND merged_into_id IS NULL) OR
         (lifecycle = 'merged' AND merged_into_id IS NOT NULL AND merged_into_id <> id))
);
ALTER TABLE issues ADD CONSTRAINT issues_merge_fk
  FOREIGN KEY (customer_id,merged_into_id) REFERENCES issues(customer_id,id);
CREATE INDEX issues_group_idx ON issues(customer_id,primary_group_id,lifecycle,updated_at DESC,id);
CREATE TABLE issue_messages (
  customer_id uuid NOT NULL,
  issue_id uuid NOT NULL,
  message_id uuid NOT NULL,
  active boolean NOT NULL DEFAULT true,
  relation text NOT NULL CHECK (relation IN ('question','answer','progress','context','correction')),
  assignment_source text NOT NULL CHECK (assignment_source IN ('ai_candidate','human_confirmed')),
  assigned_by uuid REFERENCES users(id),
  assigned_at timestamptz NOT NULL DEFAULT now(),
  removed_at timestamptz,
  FOREIGN KEY (customer_id,issue_id) REFERENCES issues(customer_id,id),
  FOREIGN KEY (customer_id,message_id) REFERENCES messages(customer_id,id),
  PRIMARY KEY (issue_id,message_id),
  CHECK (active = (removed_at IS NULL)),
  CHECK (assignment_source <> 'human_confirmed' OR assigned_by IS NOT NULL)
);
CREATE INDEX issue_messages_message_idx ON issue_messages(customer_id,message_id) WHERE active;

CREATE TABLE extraction_jobs (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES customers(id),
  kind text NOT NULL DEFAULT 'extract' CHECK (kind IN ('extract','refresh_after_topology_change')),
  batch_id uuid,
  target_issue_id uuid,
  mode text NOT NULL CHECK (mode IN ('ticket','qa','both')),
  state text NOT NULL DEFAULT 'queued' CHECK (state IN ('queued','running','succeeded','partial_failed','failed','cancel_requested','cancelled')),
  requested_by uuid NOT NULL REFERENCES users(id),
  input_hash text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  pipeline_version text NOT NULL,
  workflow_versions jsonb NOT NULL CHECK (jsonb_typeof(workflow_versions) = 'object'),
  model_profile_snapshot jsonb NOT NULL CHECK (jsonb_typeof(model_profile_snapshot) = 'object'),
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  error_code text,
  error_summary text,
  created_at timestamptz NOT NULL DEFAULT now(),
  started_at timestamptz,
  finished_at timestamptz,
  cancel_requested_at timestamptz,
  FOREIGN KEY (customer_id,batch_id) REFERENCES import_batches(customer_id,id),
  FOREIGN KEY (customer_id,target_issue_id) REFERENCES issues(customer_id,id),
  UNIQUE (customer_id,id),
  CHECK (num_nonnulls(batch_id,target_issue_id) = 1),
  CHECK (finished_at IS NULL OR (finished_at >= created_at AND (started_at IS NULL OR finished_at >= started_at)))
);
CREATE INDEX extraction_jobs_list_idx ON extraction_jobs(customer_id,created_at DESC,id);
CREATE TABLE job_steps (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  job_id uuid NOT NULL,
  stage text NOT NULL CHECK (stage IN ('parse','topic_assignment','record_extraction','validation')),
  target_key text NOT NULL,
  issue_id uuid,
  state text NOT NULL DEFAULT 'queued' CHECK (state IN ('queued','running','succeeded','failed','cancelled')),
  input_hash text NOT NULL CHECK (input_hash ~ '^[0-9a-f]{64}$'),
  workflow_version text NOT NULL,
  input_manifest jsonb NOT NULL CHECK (jsonb_typeof(input_manifest) = 'object'),
  output_json jsonb,
  attempt_count integer NOT NULL DEFAULT 0 CHECK (attempt_count >= 0),
  remote_state text NOT NULL DEFAULT 'not_started' CHECK (remote_state IN ('not_started','submitted','running','succeeded','failed','unknown')),
  dify_task_id text,
  dify_workflow_run_id text,
  remote_attempts jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(remote_attempts) = 'array'),
  lease_owner text,
  lease_until timestamptz,
  fencing_token bigint NOT NULL DEFAULT 0 CHECK (fencing_token >= 0),
  next_attempt_at timestamptz,
  error_code text,
  error_summary text,
  elapsed_ms bigint CHECK (elapsed_ms >= 0),
  token_usage jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  finished_at timestamptz,
  FOREIGN KEY (customer_id,job_id) REFERENCES extraction_jobs(customer_id,id),
  FOREIGN KEY (customer_id,issue_id) REFERENCES issues(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (job_id,stage,target_key,input_hash,workflow_version),
  CHECK (state <> 'running' OR (lease_owner IS NOT NULL AND lease_until IS NOT NULL)),
  CHECK (stage <> 'record_extraction' OR issue_id IS NOT NULL)
);
CREATE INDEX job_steps_dispatch_idx ON job_steps(state,next_attempt_at,lease_until);
CREATE INDEX job_steps_cache_idx ON job_steps(customer_id,stage,input_hash,workflow_version) WHERE state = 'succeeded';

CREATE TABLE message_dispositions (
  customer_id uuid NOT NULL,
  message_id uuid NOT NULL,
  state text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','assigned','ignored','needs_review')),
  decision_source text CHECK (decision_source IN ('rule','model_validated','human')),
  reason text NOT NULL DEFAULT '',
  decided_by uuid REFERENCES users(id),
  source_job_step_id uuid,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,message_id) REFERENCES messages(customer_id,id),
  FOREIGN KEY (customer_id,source_job_step_id) REFERENCES job_steps(customer_id,id),
  PRIMARY KEY (message_id),
  CHECK (state NOT IN ('assigned','ignored') OR decision_source IS NOT NULL),
  CHECK (decision_source <> 'human' OR decided_by IS NOT NULL)
);
CREATE INDEX message_dispositions_pending_idx ON message_dispositions(customer_id,state,message_id) WHERE state IN ('pending','needs_review');

CREATE TABLE tickets (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  issue_id uuid NOT NULL,
  ticket_no text NOT NULL UNIQUE,
  current_revision_id uuid,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,issue_id) REFERENCES issues(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,issue_id)
);
CREATE INDEX tickets_list_idx ON tickets(customer_id,updated_at DESC,id);
CREATE TABLE ticket_revisions (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  ticket_id uuid NOT NULL,
  revision_no integer NOT NULL CHECK (revision_no > 0),
  base_revision_id uuid,
  base_object_version bigint NOT NULL CHECK (base_object_version > 0),
  replaces_revision_id uuid,
  issue_input_versions jsonb NOT NULL CHECK (jsonb_typeof(issue_input_versions) = 'object'),
  group_input_versions jsonb NOT NULL CHECK (jsonb_typeof(group_input_versions) = 'object'),
  state text NOT NULL DEFAULT 'draft' CHECK (state IN ('draft','in_review','approved','rejected','superseded')),
  state_version bigint NOT NULL DEFAULT 1 CHECK (state_version > 0),
  title text NOT NULL CHECK (btrim(title) <> ''),
  first_visible_message_id uuid NOT NULL,
  first_visible_at timestamptz NOT NULL,
  first_question_message_id uuid,
  first_question_at timestamptz,
  date_basis text NOT NULL CHECK (date_basis IN ('first_question','first_visible_context')),
  ticket_date date NOT NULL,
  start_context_complete boolean NOT NULL DEFAULT true,
  problem_text text NOT NULL,
  impact_text text NOT NULL DEFAULT '',
  handling_summary text NOT NULL DEFAULT '',
  current_conclusion text NOT NULL DEFAULT '',
  claims jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(claims) = 'array'),
  next_actions jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(next_actions) = 'array'),
  status text NOT NULL CHECK (status IN ('open','in_progress','waiting_customer','waiting_internal','answered','resolved','cancelled','unknown')),
  suggested_events jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(suggested_events) = 'array'),
  risk_flags jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(risk_flags) = 'array'),
  origin text NOT NULL CHECK (origin IN ('ai','human','import')),
  source_job_step_id uuid,
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  submitted_at timestamptz,
  reviewed_by uuid REFERENCES users(id),
  reviewed_at timestamptz,
  FOREIGN KEY (customer_id,ticket_id) REFERENCES tickets(customer_id,id),
  FOREIGN KEY (customer_id,first_visible_message_id) REFERENCES messages(customer_id,id),
  FOREIGN KEY (customer_id,first_question_message_id) REFERENCES messages(customer_id,id),
  FOREIGN KEY (customer_id,source_job_step_id) REFERENCES job_steps(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,ticket_id,id),
  UNIQUE (ticket_id,revision_no),
  CHECK (num_nonnulls(first_question_message_id,first_question_at) IN (0,2)),
  CHECK ((date_basis = 'first_question' AND first_question_message_id IS NOT NULL) OR
         (date_basis = 'first_visible_context' AND first_question_message_id IS NULL)),
  CHECK (ticket_date = ((CASE WHEN date_basis = 'first_question' THEN first_question_at ELSE first_visible_at END) AT TIME ZONE 'Asia/Shanghai')::date),
  CHECK (base_revision_id IS NULL OR base_revision_id <> id),
  CHECK (replaces_revision_id IS NULL OR replaces_revision_id <> id),
  CHECK (state NOT IN ('approved','rejected') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CHECK (origin <> 'ai' OR source_job_step_id IS NOT NULL)
);
ALTER TABLE ticket_revisions ADD CONSTRAINT ticket_revisions_base_fk
  FOREIGN KEY (customer_id,ticket_id,base_revision_id) REFERENCES ticket_revisions(customer_id,ticket_id,id);
ALTER TABLE ticket_revisions ADD CONSTRAINT ticket_revisions_replaces_fk
  FOREIGN KEY (customer_id,ticket_id,replaces_revision_id) REFERENCES ticket_revisions(customer_id,ticket_id,id);
ALTER TABLE tickets ADD CONSTRAINT tickets_current_revision_fk
  FOREIGN KEY (customer_id,id,current_revision_id) REFERENCES ticket_revisions(customer_id,ticket_id,id)
  DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX ticket_revisions_queue_idx ON ticket_revisions(customer_id,state,created_at,id);
CREATE INDEX ticket_revisions_date_idx ON ticket_revisions(customer_id,ticket_date,status);

CREATE TABLE ticket_events (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  ticket_id uuid NOT NULL,
  source_revision_id uuid NOT NULL,
  event_key text NOT NULL,
  kind text NOT NULL CHECK (kind IN ('customer_message','support_reply','status_change','correction','follow_up','requirement_submitted')),
  occurred_at timestamptz NOT NULL,
  occurred_at_basis text NOT NULL CHECK (occurred_at_basis IN ('source_message','human_recorded','approval_time')),
  summary text NOT NULL,
  status_from text CHECK (status_from IN ('open','in_progress','waiting_customer','waiting_internal','answered','resolved','cancelled','unknown')),
  status_to text CHECK (status_to IN ('open','in_progress','waiting_customer','waiting_internal','answered','resolved','cancelled','unknown')),
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,ticket_id,source_revision_id) REFERENCES ticket_revisions(customer_id,ticket_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (ticket_id,event_key),
  CHECK (kind <> 'status_change' OR status_to IS NOT NULL)
);
CREATE INDEX ticket_events_timeline_idx ON ticket_events(customer_id,ticket_id,occurred_at,id);
CREATE INDEX ticket_events_daily_idx ON ticket_events(customer_id,occurred_at,ticket_id);

CREATE TABLE ticket_notes (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  ticket_id uuid NOT NULL,
  author_id uuid NOT NULL REFERENCES users(id),
  body text NOT NULL CHECK (length(body) BETWEEN 1 AND 4000),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,ticket_id) REFERENCES tickets(customer_id,id),
  UNIQUE (customer_id,id)
);
CREATE INDEX ticket_notes_timeline_idx ON ticket_notes(customer_id,ticket_id,created_at,id);

CREATE TABLE qa_entries (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL REFERENCES customers(id),
  qa_no text NOT NULL UNIQUE,
  current_revision_id uuid,
  lifecycle text NOT NULL DEFAULT 'active' CHECK (lifecycle IN ('active','withdrawn')),
  withdrawn_at timestamptz,
  version bigint NOT NULL DEFAULT 1 CHECK (version > 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),
  UNIQUE (customer_id,id),
  CHECK ((lifecycle = 'active' AND withdrawn_at IS NULL) OR (lifecycle = 'withdrawn' AND withdrawn_at IS NOT NULL))
);
CREATE INDEX qa_entries_list_idx ON qa_entries(customer_id,lifecycle,updated_at DESC,id);
CREATE TABLE qa_revisions (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  qa_id uuid NOT NULL,
  revision_no integer NOT NULL CHECK (revision_no > 0),
  base_revision_id uuid,
  base_object_version bigint NOT NULL CHECK (base_object_version > 0),
  replaces_revision_id uuid,
  issue_input_versions jsonb NOT NULL CHECK (jsonb_typeof(issue_input_versions) = 'object'),
  group_input_versions jsonb NOT NULL CHECK (jsonb_typeof(group_input_versions) = 'object'),
  state text NOT NULL DEFAULT 'draft' CHECK (state IN ('draft','in_review','approved','rejected','superseded')),
  state_version bigint NOT NULL DEFAULT 1 CHECK (state_version > 0),
  question text NOT NULL CHECK (btrim(question) <> ''),
  answer text,
  answer_claims jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(answer_claims) = 'array'),
  answer_state text NOT NULL CHECK (answer_state IN ('supported','no_answer','conflict','missing_context')),
  applicability text NOT NULL DEFAULT '',
  as_of_date date,
  risk_flags jsonb NOT NULL DEFAULT '[]' CHECK (jsonb_typeof(risk_flags) = 'array'),
  origin text NOT NULL CHECK (origin IN ('ai','human','import')),
  source_job_step_id uuid,
  created_by uuid REFERENCES users(id),
  created_at timestamptz NOT NULL DEFAULT now(),
  submitted_at timestamptz,
  reviewed_by uuid REFERENCES users(id),
  reviewed_at timestamptz,
  FOREIGN KEY (customer_id,qa_id) REFERENCES qa_entries(customer_id,id),
  FOREIGN KEY (customer_id,source_job_step_id) REFERENCES job_steps(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,qa_id,id),
  UNIQUE (qa_id,revision_no),
  CHECK (state <> 'approved' OR (answer_state = 'supported' AND answer IS NOT NULL AND btrim(answer) <> '')),
  CHECK (base_revision_id IS NULL OR base_revision_id <> id),
  CHECK (replaces_revision_id IS NULL OR replaces_revision_id <> id),
  CHECK (state NOT IN ('approved','rejected') OR (reviewed_by IS NOT NULL AND reviewed_at IS NOT NULL)),
  CHECK (origin <> 'ai' OR source_job_step_id IS NOT NULL)
);
ALTER TABLE qa_revisions ADD CONSTRAINT qa_revisions_base_fk
  FOREIGN KEY (customer_id,qa_id,base_revision_id) REFERENCES qa_revisions(customer_id,qa_id,id);
ALTER TABLE qa_revisions ADD CONSTRAINT qa_revisions_replaces_fk
  FOREIGN KEY (customer_id,qa_id,replaces_revision_id) REFERENCES qa_revisions(customer_id,qa_id,id);
ALTER TABLE qa_entries ADD CONSTRAINT qa_entries_current_revision_fk
  FOREIGN KEY (customer_id,id,current_revision_id) REFERENCES qa_revisions(customer_id,qa_id,id)
  DEFERRABLE INITIALLY DEFERRED;
CREATE INDEX qa_revisions_queue_idx ON qa_revisions(customer_id,state,created_at,id);

CREATE TABLE qa_issue_links (
  customer_id uuid NOT NULL,
  qa_revision_id uuid NOT NULL,
  issue_id uuid NOT NULL,
  FOREIGN KEY (customer_id,qa_revision_id) REFERENCES qa_revisions(customer_id,id),
  FOREIGN KEY (customer_id,issue_id) REFERENCES issues(customer_id,id),
  PRIMARY KEY (qa_revision_id,issue_id)
);
CREATE INDEX qa_issue_links_issue_idx ON qa_issue_links(customer_id,issue_id);
CREATE TABLE qa_contributors (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  qa_revision_id uuid NOT NULL,
  participant_id uuid NOT NULL,
  contribution text NOT NULL,
  is_core boolean NOT NULL DEFAULT true,
  FOREIGN KEY (customer_id,qa_revision_id) REFERENCES qa_revisions(customer_id,id),
  FOREIGN KEY (customer_id,participant_id) REFERENCES participants(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (qa_revision_id,participant_id)
);

CREATE TABLE evidence_spans (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  message_id uuid NOT NULL,
  start_cp integer NOT NULL CHECK (start_cp >= 0),
  end_cp integer NOT NULL CHECK (end_cp > start_cp),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,message_id) REFERENCES messages(customer_id,id),
  UNIQUE (customer_id,id),
  UNIQUE (customer_id,message_id,start_cp,end_cp)
);
CREATE TABLE revision_evidence (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  ticket_revision_id uuid,
  qa_revision_id uuid,
  field_key text NOT NULL,
  evidence_span_id uuid NOT NULL,
  relation text NOT NULL CHECK (relation IN ('supports','contradicts','context')),
  FOREIGN KEY (customer_id,ticket_revision_id) REFERENCES ticket_revisions(customer_id,id),
  FOREIGN KEY (customer_id,qa_revision_id) REFERENCES qa_revisions(customer_id,id),
  FOREIGN KEY (customer_id,evidence_span_id) REFERENCES evidence_spans(customer_id,id),
  CHECK (num_nonnulls(ticket_revision_id,qa_revision_id) = 1)
);
CREATE UNIQUE INDEX revision_evidence_ticket_uq ON revision_evidence(ticket_revision_id,field_key,evidence_span_id,relation) WHERE ticket_revision_id IS NOT NULL;
CREATE UNIQUE INDEX revision_evidence_qa_uq ON revision_evidence(qa_revision_id,field_key,evidence_span_id,relation) WHERE qa_revision_id IS NOT NULL;
CREATE TABLE event_evidence (
  customer_id uuid NOT NULL,
  ticket_event_id uuid NOT NULL,
  evidence_span_id uuid NOT NULL,
  FOREIGN KEY (customer_id,ticket_event_id) REFERENCES ticket_events(customer_id,id),
  FOREIGN KEY (customer_id,evidence_span_id) REFERENCES evidence_spans(customer_id,id),
  PRIMARY KEY (ticket_event_id,evidence_span_id)
);
CREATE TABLE ticket_note_evidence (
  customer_id uuid NOT NULL,
  ticket_note_id uuid NOT NULL,
  evidence_span_id uuid NOT NULL,
  FOREIGN KEY (customer_id,ticket_note_id) REFERENCES ticket_notes(customer_id,id),
  FOREIGN KEY (customer_id,evidence_span_id) REFERENCES evidence_spans(customer_id,id),
  PRIMARY KEY (ticket_note_id,evidence_span_id)
);
CREATE TABLE contributor_evidence (
  customer_id uuid NOT NULL,
  contributor_id uuid NOT NULL,
  evidence_span_id uuid NOT NULL,
  message_annotation_id uuid,
  FOREIGN KEY (customer_id,contributor_id) REFERENCES qa_contributors(customer_id,id),
  FOREIGN KEY (customer_id,evidence_span_id) REFERENCES evidence_spans(customer_id,id),
  FOREIGN KEY (customer_id,message_annotation_id) REFERENCES message_annotations(customer_id,id),
  PRIMARY KEY (contributor_id,evidence_span_id)
);

CREATE TABLE review_actions (
  id uuid PRIMARY KEY,
  customer_id uuid NOT NULL,
  ticket_revision_id uuid,
  qa_revision_id uuid,
  action text NOT NULL CHECK (action IN ('submit','approve','reject','supersede','rebase')),
  actor_id uuid NOT NULL REFERENCES users(id),
  reason text NOT NULL DEFAULT '',
  checks_snapshot jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(checks_snapshot) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now(),
  FOREIGN KEY (customer_id,ticket_revision_id) REFERENCES ticket_revisions(customer_id,id),
  FOREIGN KEY (customer_id,qa_revision_id) REFERENCES qa_revisions(customer_id,id),
  CHECK (num_nonnulls(ticket_revision_id,qa_revision_id) = 1)
);
CREATE INDEX review_actions_customer_idx ON review_actions(customer_id,created_at DESC,id);
CREATE TABLE audit_logs (
  id uuid PRIMARY KEY,
  customer_id uuid REFERENCES customers(id),
  actor_user_id uuid REFERENCES users(id),
  actor_kind text NOT NULL CHECK (actor_kind IN ('user','worker','system')),
  action text NOT NULL,
  object_type text NOT NULL,
  object_id uuid,
  request_id uuid,
  changes_summary jsonb NOT NULL DEFAULT '{}' CHECK (jsonb_typeof(changes_summary) = 'object'),
  created_at timestamptz NOT NULL DEFAULT now()
);
CREATE INDEX audit_logs_customer_idx ON audit_logs(customer_id,created_at DESC,id);
CREATE TABLE idempotency_records (
  id uuid PRIMARY KEY,
  user_id uuid NOT NULL REFERENCES users(id),
  http_method text NOT NULL,
  request_path text NOT NULL,
  idempotency_key text NOT NULL CHECK (length(idempotency_key) BETWEEN 1 AND 128),
  request_hash text NOT NULL CHECK (request_hash ~ '^[0-9a-f]{64}$'),
  state text NOT NULL CHECK (state IN ('in_progress','completed')),
  response_status integer CHECK (response_status BETWEEN 200 AND 599),
  response_body jsonb,
  response_headers jsonb,
  created_at timestamptz NOT NULL DEFAULT now(),
  expires_at timestamptz NOT NULL,
  UNIQUE (user_id,http_method,request_path,idempotency_key),
  CHECK (expires_at > created_at),
  CHECK (state <> 'completed' OR response_status IS NOT NULL)
);
CREATE INDEX idempotency_records_expiry_idx ON idempotency_records(expires_at);
CREATE TABLE outbox_events (
  id uuid PRIMARY KEY,
  customer_id uuid REFERENCES customers(id),
  event_type text NOT NULL,
  aggregate_type text NOT NULL,
  aggregate_id uuid NOT NULL,
  dedupe_key text NOT NULL UNIQUE,
  payload jsonb NOT NULL CHECK (jsonb_typeof(payload) = 'object'),
  state text NOT NULL DEFAULT 'pending' CHECK (state IN ('pending','publishing','published','failed')),
  attempts integer NOT NULL DEFAULT 0 CHECK (attempts >= 0),
  available_at timestamptz NOT NULL DEFAULT now(),
  lease_owner text,
  lease_until timestamptz,
  fencing_token bigint NOT NULL DEFAULT 0 CHECK (fencing_token >= 0),
  created_at timestamptz NOT NULL DEFAULT now(),
  published_at timestamptz,
  last_error_code text,
  CHECK (state <> 'publishing' OR (lease_owner IS NOT NULL AND lease_until IS NOT NULL))
);
CREATE INDEX outbox_dispatch_idx ON outbox_events(state,available_at,lease_until);

-- Immutability is enforced for rows; permissions must also prevent TRUNCATE.
CREATE FUNCTION reject_row_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only; create a new version/correction', TG_TABLE_NAME;
END;
$$;
CREATE TRIGGER messages_immutable BEFORE UPDATE OR DELETE ON messages FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER import_parse_snapshots_immutable BEFORE UPDATE OR DELETE ON import_parse_snapshots FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER message_annotations_immutable BEFORE UPDATE OR DELETE ON message_annotations FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER evidence_spans_immutable BEFORE UPDATE OR DELETE ON evidence_spans FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER ticket_events_immutable BEFORE UPDATE OR DELETE ON ticket_events FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER ticket_notes_immutable BEFORE UPDATE OR DELETE ON ticket_notes FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER ticket_note_evidence_immutable BEFORE UPDATE OR DELETE ON ticket_note_evidence FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER qa_issue_links_immutable BEFORE UPDATE OR DELETE ON qa_issue_links FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER qa_contributors_immutable BEFORE UPDATE OR DELETE ON qa_contributors FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER revision_evidence_immutable BEFORE UPDATE OR DELETE ON revision_evidence FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER event_evidence_immutable BEFORE UPDATE OR DELETE ON event_evidence FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER contributor_evidence_immutable BEFORE UPDATE OR DELETE ON contributor_evidence FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER review_actions_immutable BEFORE UPDATE OR DELETE ON review_actions FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();
CREATE TRIGGER audit_logs_immutable BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION reject_row_mutation();

CREATE FUNCTION guard_revision_mutation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE allowed_keys text[] := ARRAY['state','state_version','submitted_at','reviewed_by','reviewed_at'];
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.state <> 'draft' OR NEW.state_version <> 1 OR NEW.submitted_at IS NOT NULL OR NEW.reviewed_by IS NOT NULL OR NEW.reviewed_at IS NOT NULL THEN
      RAISE EXCEPTION 'New revisions must start as unreviewed drafts';
    END IF;
    RETURN NEW;
  END IF;
  IF TG_OP = 'DELETE' THEN RAISE EXCEPTION 'Revision deletion is forbidden'; END IF;
  IF (to_jsonb(NEW) - allowed_keys) IS DISTINCT FROM (to_jsonb(OLD) - allowed_keys) THEN
    RAISE EXCEPTION 'Revision payload is immutable; create another revision';
  END IF;
  IF NOT ((OLD.state = 'draft' AND NEW.state IN ('in_review','superseded')) OR
          (OLD.state = 'in_review' AND NEW.state IN ('approved','rejected','superseded'))) THEN
    RAISE EXCEPTION 'Invalid revision state transition: % -> %', OLD.state, NEW.state;
  END IF;
  IF NEW.state_version <> OLD.state_version + 1 THEN RAISE EXCEPTION 'state_version must increment'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER ticket_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON ticket_revisions FOR EACH ROW EXECUTE FUNCTION guard_revision_mutation();
CREATE TRIGGER qa_revision_guard BEFORE INSERT OR UPDATE OR DELETE ON qa_revisions FOR EACH ROW EXECUTE FUNCTION guard_revision_mutation();

CREATE FUNCTION check_evidence_span() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE n integer;
BEGIN
  SELECT char_length(raw_text) INTO n FROM messages WHERE customer_id = NEW.customer_id AND id = NEW.message_id;
  IF n IS NULL OR NEW.end_cp > n THEN RAISE EXCEPTION 'Evidence offsets are outside raw_text'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER evidence_span_bounds BEFORE INSERT ON evidence_spans FOR EACH ROW EXECUTE FUNCTION check_evidence_span();

CREATE FUNCTION check_current_approved_revision() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE ptr uuid; revision_state text;
BEGIN
  IF TG_TABLE_NAME = 'tickets' THEN
    SELECT current_revision_id INTO ptr FROM tickets WHERE id = NEW.id;
    IF ptr IS NULL THEN RETURN NULL; END IF;
    SELECT state INTO revision_state FROM ticket_revisions WHERE id = ptr AND ticket_id = NEW.id AND customer_id = NEW.customer_id;
  ELSE
    SELECT current_revision_id INTO ptr FROM qa_entries WHERE id = NEW.id;
    IF ptr IS NULL THEN RETURN NULL; END IF;
    SELECT state INTO revision_state FROM qa_revisions WHERE id = ptr AND qa_id = NEW.id AND customer_id = NEW.customer_id;
  END IF;
  IF revision_state IS DISTINCT FROM 'approved' THEN RAISE EXCEPTION 'Current revision must be approved'; END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER tickets_current_approved AFTER INSERT OR UPDATE ON tickets
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_current_approved_revision();
CREATE CONSTRAINT TRIGGER qa_current_approved AFTER INSERT OR UPDATE ON qa_entries
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_current_approved_revision();

CREATE FUNCTION check_direct_contributor() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE expected_sender uuid; actual_sender uuid; is_direct boolean;
        raw_message_id uuid; cp_start integer; cp_end integer; direct_spans jsonb;
BEGIN
  SELECT participant_id INTO expected_sender FROM qa_contributors WHERE id = NEW.contributor_id AND customer_id = NEW.customer_id;
  SELECT m.id,m.sender_participant_id,m.direct_body_spans,e.start_cp,e.end_cp
    INTO raw_message_id,actual_sender,direct_spans,cp_start,cp_end
    FROM evidence_spans e JOIN messages m ON m.id = e.message_id AND m.customer_id = e.customer_id
    WHERE e.id = NEW.evidence_span_id AND e.customer_id = NEW.customer_id;
  IF NEW.message_annotation_id IS NOT NULL THEN
    SELECT a.sender_participant_id,a.direct_body_spans INTO actual_sender,direct_spans
      FROM message_annotations a WHERE a.id = NEW.message_annotation_id
      AND a.customer_id = NEW.customer_id AND a.message_id = raw_message_id;
  END IF;
  SELECT EXISTS (SELECT 1 FROM jsonb_array_elements(direct_spans) s
    WHERE (s->>'start_cp')::integer <= cp_start AND (s->>'end_cp')::integer >= cp_end) INTO is_direct;
  IF expected_sender IS NULL OR actual_sender IS DISTINCT FROM expected_sender OR NOT coalesce(is_direct,false) THEN
    RAISE EXCEPTION 'Contributor evidence must be a direct message by this participant';
  END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER contributor_direct_speaker BEFORE INSERT ON contributor_evidence FOR EACH ROW EXECUTE FUNCTION check_direct_contributor();

-- Freeze associations as well as payloads when a revision leaves draft.
CREATE FUNCTION guard_revision_child_insert() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE parent_id uuid; parent_state text; use_ticket boolean := false;
BEGIN
  IF TG_TABLE_NAME = 'revision_evidence' THEN
    use_ticket := NEW.ticket_revision_id IS NOT NULL;
    parent_id := coalesce(NEW.ticket_revision_id,NEW.qa_revision_id);
  ELSIF TG_TABLE_NAME = 'contributor_evidence' THEN
    SELECT qa_revision_id INTO parent_id FROM qa_contributors WHERE id = NEW.contributor_id AND customer_id = NEW.customer_id;
  ELSE
    parent_id := NEW.qa_revision_id;
  END IF;
  IF use_ticket THEN
    SELECT state INTO parent_state FROM ticket_revisions WHERE id = parent_id AND customer_id = NEW.customer_id FOR SHARE;
  ELSE
    SELECT state INTO parent_state FROM qa_revisions WHERE id = parent_id AND customer_id = NEW.customer_id FOR SHARE;
  END IF;
  IF parent_state IS DISTINCT FROM 'draft' THEN RAISE EXCEPTION 'Revision associations are frozen outside draft'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER revision_evidence_draft_only BEFORE INSERT ON revision_evidence FOR EACH ROW EXECUTE FUNCTION guard_revision_child_insert();
CREATE TRIGGER qa_issue_links_draft_only BEFORE INSERT ON qa_issue_links FOR EACH ROW EXECUTE FUNCTION guard_revision_child_insert();
CREATE TRIGGER qa_contributors_draft_only BEFORE INSERT ON qa_contributors FOR EACH ROW EXECUTE FUNCTION guard_revision_child_insert();
CREATE TRIGGER contributor_evidence_draft_only BEFORE INSERT ON contributor_evidence FOR EACH ROW EXECUTE FUNCTION guard_revision_child_insert();

CREATE FUNCTION guard_event_creation() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE revision_id uuid; parent_state text;
BEGIN
  IF TG_TABLE_NAME = 'ticket_events' THEN revision_id := NEW.source_revision_id;
  ELSE SELECT source_revision_id INTO revision_id FROM ticket_events WHERE id = NEW.ticket_event_id AND customer_id = NEW.customer_id;
  END IF;
  SELECT state INTO parent_state FROM ticket_revisions WHERE id = revision_id AND customer_id = NEW.customer_id FOR SHARE;
  IF parent_state IS DISTINCT FROM 'in_review' THEN RAISE EXCEPTION 'Events and evidence must be created within approval transaction'; END IF;
  RETURN NEW;
END;
$$;
CREATE TRIGGER ticket_events_creation_guard BEFORE INSERT ON ticket_events FOR EACH ROW EXECUTE FUNCTION guard_event_creation();
CREATE TRIGGER event_evidence_creation_guard BEFORE INSERT ON event_evidence FOR EACH ROW EXECUTE FUNCTION guard_event_creation();
CREATE FUNCTION check_event_approved_at_commit() RETURNS trigger LANGUAGE plpgsql AS $$
DECLARE parent_state text;
BEGIN
  SELECT state INTO parent_state FROM ticket_revisions WHERE id = NEW.source_revision_id AND customer_id = NEW.customer_id;
  IF parent_state IS DISTINCT FROM 'approved' THEN RAISE EXCEPTION 'Committed event must reference an approved revision'; END IF;
  RETURN NULL;
END;
$$;
CREATE CONSTRAINT TRIGGER ticket_events_approved_at_commit AFTER INSERT ON ticket_events
  DEFERRABLE INITIALLY DEFERRED FOR EACH ROW EXECUTE FUNCTION check_event_approved_at_commit();

COMMENT ON COLUMN messages.raw_text IS 'Exact body substring of decoded source, no whitespace/newline normalization; immutable.';
COMMENT ON COLUMN messages.direct_body_spans IS 'Array of {start_cp,end_cp} in raw_text; parser-confirmed direct prose excluding quote/reply blocks. Unknown means empty.';
COMMENT ON COLUMN message_annotations.direct_body_spans IS 'Corrected direct-prose ranges still refer to immutable messages.raw_text; must be bounds-checked by service.';
COMMENT ON COLUMN contributor_evidence.message_annotation_id IS 'Interpretation snapshot used for attribution; null means original messages parse. Never silently read latest for historical attribution.';
COMMENT ON COLUMN messages.source_body_start IS 'Zero-based Unicode code point offset in the decoded complete source, inclusive.';
COMMENT ON COLUMN messages.source_body_end IS 'Zero-based Unicode code point offset in the decoded complete source, exclusive.';
COMMENT ON COLUMN evidence_spans.start_cp IS 'Zero-based Unicode code points in messages.raw_text; never UTF-16 code units or bytes.';
COMMENT ON COLUMN evidence_spans.end_cp IS 'Exclusive Unicode code point end offset in messages.raw_text.';
COMMENT ON COLUMN issues.message_version IS 'Increment atomically for membership, identity, quote interpretation or source correction affecting extraction inputs.';
COMMENT ON COLUMN ticket_revisions.base_revision_id IS 'Approved version observed when this candidate was created; null only if none existed.';
COMMENT ON COLUMN ticket_revisions.replaces_revision_id IS 'Optional candidate being edited/rebased; payload edits always create a new row.';
COMMENT ON COLUMN ticket_revisions.issue_input_versions IS 'Object mapping same-customer issue UUID strings to observed message_version integer values.';
COMMENT ON COLUMN qa_revisions.issue_input_versions IS 'Object mapping same-customer issue UUID strings to observed message_version integer values; must equal qa_issue_links set.';
COMMENT ON COLUMN ticket_revisions.group_input_versions IS 'Object mapping same-customer group UUID strings to ingestion_version; approval requires each group classified_version = ingestion_version = snapshot.';
COMMENT ON COLUMN qa_revisions.group_input_versions IS 'Same group gate as ticket revisions; prevents approving while imported corrections remain unclassified.';
COMMENT ON COLUMN audit_logs.object_id IS 'Audit label, not an authorization or referential-integrity anchor.';
COMMENT ON COLUMN outbox_events.payload IS 'Identifiers and dispatch metadata only; no full chat text or secrets.';

COMMIT;
